mapper.select:
SELECT  FROM t_product_capability
WHERE capability_code IN #{code}
ORDER BY product_capability_id

mapper.update:
UPDATE t_product_capability SET status = #{status}, change_version = change_version + 1, update_time = #{now}
WHERE product_capability_id = #{capability.productCapabilityId} AND status = #{capability.status}
  AND change_version = #{capability.changeVersion}

UPDATE t_product_capability
SET capability_name = #{capabilityName}, product_code = #{productCode}, change_version = change_version + 1,
    update_time = #{now}
WHERE product_capability_id = #{capability.productCapabilityId} AND change_version = #{capability.changeVersion}

mapper.select:
